/* Translation that keeps working on free allowances (round 13): translation_provider_state keeps, per translator (Gemini, Cloudflare Workers AI and the others), the models it read from the provider's own list today, which models are resting and until when (asked too fast, today's free allowance used, retired), and its last success and last failure, so every run and every server instance skips a model another found out of allowance instead of asking it again; translation_provider_usage counts calls, texts, characters and tokens per day, translator and model, for /admin/translations, through translation_usage_add; translation_refusals keeps, by language pair and the sha256 of a text, a text whose every machine translation failed the checks (a price changed, words added, a placeholder lost), so it waits an hour, then longer each time, instead of being sent again every few minutes. translation_memory may now also keep what Cloudflare Workers AI translated. New tables and one function; no existing row changes. Server only: row level security on, nothing granted to anon or signed in users. Until it runs, translating works as before, each server instance keeping its own rests, and /admin/translations says this part is needed. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.translation_provider_state (provider text PRIMARY KEY CHECK (length(provider) BETWEEN 2 AND 40), models jsonb, models_hash text, listed_at timestamptz, rests jsonb NOT NULL DEFAULT '{}'::jsonb, last_ok_at timestamptz, last_error text CHECK (last_error IS NULL OR length(last_error) <= 600), last_error_kind text, last_error_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.translation_provider_usage (day date NOT NULL, provider text NOT NULL CHECK (length(provider) BETWEEN 2 AND 40), model text NOT NULL CHECK (length(model) BETWEEN 1 AND 120), calls integer NOT NULL DEFAULT 0, ok integer NOT NULL DEFAULT 0, failed integer NOT NULL DEFAULT 0, limited integer NOT NULL DEFAULT 0, strings integer NOT NULL DEFAULT 0, chars bigint NOT NULL DEFAULT 0, input_tokens bigint NOT NULL DEFAULT 0, output_tokens bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (day, provider, model));
CREATE INDEX IF NOT EXISTS translation_provider_usage_day_idx ON public.translation_provider_usage (day DESC);
CREATE TABLE IF NOT EXISTS public.translation_refusals (source_lang text NOT NULL CHECK (length(source_lang) BETWEEN 2 AND 12), target_lang text NOT NULL CHECK (length(target_lang) BETWEEN 2 AND 12), source_hash text NOT NULL CHECK (source_hash ~ '^[0-9a-f]{64}$'), tries integer NOT NULL DEFAULT 1, retry_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (source_lang, target_lang, source_hash));
ALTER TABLE public.translation_provider_state ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.translation_provider_usage ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.translation_refusals ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.translation_provider_state FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.translation_provider_usage FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.translation_refusals FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.translation_provider_state TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.translation_provider_usage TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.translation_refusals TO service_role;
CREATE OR REPLACE FUNCTION public.translation_usage_add(p_day date, p_provider text, p_model text, p_calls integer DEFAULT 0, p_ok integer DEFAULT 0, p_failed integer DEFAULT 0, p_limited integer DEFAULT 0, p_strings integer DEFAULT 0, p_chars bigint DEFAULT 0, p_input_tokens bigint DEFAULT 0, p_output_tokens bigint DEFAULT 0) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $f$ INSERT INTO public.translation_provider_usage AS u (day, provider, model, calls, ok, failed, limited, strings, chars, input_tokens, output_tokens, updated_at) VALUES (p_day, left(p_provider, 40), left(coalesce(nullif(p_model, ''), '-'), 120), greatest(p_calls, 0), greatest(p_ok, 0), greatest(p_failed, 0), greatest(p_limited, 0), greatest(p_strings, 0), greatest(p_chars, 0), greatest(p_input_tokens, 0), greatest(p_output_tokens, 0), now()) ON CONFLICT (day, provider, model) DO UPDATE SET calls = u.calls + excluded.calls, ok = u.ok + excluded.ok, failed = u.failed + excluded.failed, limited = u.limited + excluded.limited, strings = u.strings + excluded.strings, chars = u.chars + excluded.chars, input_tokens = u.input_tokens + excluded.input_tokens, output_tokens = u.output_tokens + excluded.output_tokens, updated_at = now(); $f$;
REVOKE ALL ON FUNCTION public.translation_usage_add(date, text, text, integer, integer, integer, integer, integer, bigint, bigint, bigint) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.translation_usage_add(date, text, text, integer, integer, integer, integer, integer, bigint, bigint, bigint) TO service_role;
DO $do$ BEGIN IF to_regclass('public.translation_memory') IS NOT NULL THEN ALTER TABLE public.translation_memory DROP CONSTRAINT IF EXISTS translation_memory_provider_check; ALTER TABLE public.translation_memory ADD CONSTRAINT translation_memory_provider_check CHECK (provider IN ('gemini', 'cloudflare', 'deepl', 'libretranslate', 'huggingface', 'llm', 'mymemory', 'openai')); END IF; END $do$;
notify pgrst, 'reload schema';
